package disaster.rescue; public class ThreadDemo {public static void main(String[]a)throws Exception{Thread t=new Thread(()->{try{Thread.sleep(20);}catch(InterruptedException e){Thread.currentThread().interrupt();}},"state-demo");System.out.println("NEW="+t.getState());t.start();System.out.println("RUNNING/WAITING="+t.getState());t.join();System.out.println("TERMINATED="+t.getState());}}
